var OAuthTokenGenerator = Class.create();
OAuthTokenGenerator.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {



    getOAuthToken: function() {

        try {
            var requestBody = 'grant_type=password' +
                '&client_id=' + encodeURIComponent(gs.getProperty('x_938076_now_utils.dev225873ClientID')) +
                '&client_secret=' + encodeURIComponent(gs.getProperty('x_938076_now_utils.dev225873ClientSecret')) +
                '&username=' + encodeURIComponent(gs.getProperty('x_938076_now_utils.dev225873UserName')) +
                '&password=' + encodeURIComponent(gs.getProperty('x_938076_now_utils.dev225873UserPassword'));

            var restMessage = new sn_ws.RESTMessageV2();
            restMessage.setEndpoint(gs.getProperty('x_938076_now_utils.dev225873EndPoint') + 'oauth_token.do');
            restMessage.setHttpMethod('POST');
            restMessage.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
            restMessage.setRequestBody(requestBody);

            var response = restMessage.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            if (httpStatus === 200) {
                var tokenResponse = JSON.parse(responseBody);
                gs.info('OAuth Access Token: ' + tokenResponse.access_token);
                gs.info('OAuth Refresh Token: ' + tokenResponse.refresh_token);
                gs.setProperty('x_938076_now_utils.dev225873Accesstoken', "Bearer " + tokenResponse.access_token);
                gs.setProperty('x_938076_now_utils.dev225873Refreshtoken', "Bearer " + tokenResponse.refresh_token);
                return tokenResponse;
            } else {
                gs.error('Failed to get OAuth token. Status: ' + httpStatus + ', Response: ' + responseBody);
                return null;
            }
        } catch (ex) {
            gs.error('Exception in getOAuthToken: ' + ex.getMessage());
            return null;
        }
    },

    refreshToken: function() {

        try {
            var requestBody = 'grant_type=refresh_token' +
                '&client_id=' + encodeURIComponent(gs.getProperty('x_938076_now_utils.dev225873ClientID')) +
                '&client_secret=' + encodeURIComponent(gs.getProperty('x_938076_now_utils.dev225873ClientSecret')) +
                '&refresh_token=' + gs.getProperty('x_938076_now_utils.dev225873Refreshtoken'); //accesstoken

            var restMessage = new sn_ws.RESTMessageV2();
            restMessage.setEndpoint(gs.getProperty('x_938076_now_utils.dev225873EndPoint') + 'oauth_token.do');
            restMessage.setHttpMethod('POST');
            restMessage.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
            restMessage.setRequestBody(requestBody);

            var response = restMessage.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            if (httpStatus === 200) { //if accesstoken received
                var tokenResponse = JSON.parse(responseBody);
                gs.info('There was exisitng accesstoken working so no credentials used');
                gs.setProperty('x_938076_now_utils.dev225873Accesstoken', "Bearer " + tokenResponse.access_token);
                gs.setProperty('x_938076_now_utils.dev225873Refreshtoken', "Bearer " + tokenResponse.refresh_token);
            } else { //triggering using credentials to get accesstoken
                gs.info('Access token failed using credentials');
                var newRefreskTokenCall = this.getOAuthToken();
                gs.setProperty('x_938076_now_utils.dev225873Accesstoken', "Bearer " + newRefreskTokenCall.access_token);
                gs.setProperty('x_938076_now_utils.dev225873Refreshtoken', "Bearer " + newRefreskTokenCall.refresh_token);
            }
        } catch (ex) {
            gs.error('Exception in getOAuthToken: ' + ex.getMessage());
            return null;
        }
    },






    getIncidents: function(incidentSysId) {
        // var dynamicBearerToken = //call method to obtain token

        try {
            var restMessage = new sn_ws.RESTMessageV2('Custom OAuth Message', 'Default GET');
            restMessage.setStringParameter('sys_id', incidentSysId);
            restMessage.setStringParameter('Authorization', 'Bearer ' + gs.getProperty('dev347183Accesstoken'));
            var response = restMessage.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            gs.info("Incident API Call Successful. HTTP Status: " + httpStatus);

            if (httpStatus >= 200 && httpStatus < 300) {
                var jsonResponse = JSON.parse(responseBody);
                gs.info("Successfully retrieved incident number: " + jsonResponse.result.number);
            } else {
                gs.info('Recalling the function due to failure');
                this.refreshToken(); //calling the refresh token to refresh if the status code failed
                this.getIncidents(incidentSysId); // and calling back the function

                gs.info("Incident API Call Failed. Status: " + httpStatus + ", Body: " + responseBody);
            }

        } catch (ex) {
            gs.error("REST Message Execution Exception: " + ex);
            var message = ex.getMessage();
            gs.error("Detailed Exception Message: " + message);
        }
    },


    createIncidents: function(incidentSysId) {
        // 1. Identify fields to skip (system fields, journal fields, large data types)
        // These fields are either generated by the target system or shouldn't be copied directly.
        var fieldsToSkip = [
            'sys_id', // Target must generate its own
            'sys_created_on',
            'sys_updated_on',
            'sys_mod_count',
            'sys_created_by',
            'sys_updated_by',
            '__row_data', // Internal system field
            'comments', // Journal fields should be handled separately if needed
            'work_notes',
            'activity_due', // Often recalculated
            'due_date', // Often recalculated
            // Add any other fields you know must be skipped
        ];

        var payload = {};

        // 2. Iterate through all fields of the Incident record with limited fields
        var gr = new GlideRecord('incident');
        gr.get(incidentSysId); // Only needed to get the field list, not to query data

        var fields = gr.getFields();

        for (var i = 0; i < fields.size(); i++) {
            var field = fields.get(i);
            var fieldName = field.getName();

            // 3. Check if the field should be skipped
            if (fieldsToSkip.indexOf(fieldName) > -1) {
                continue;
            }

            // 4. Get the field value
            var value = gr.getValue(fieldName);
            if (field.isReference()) {
                // Add the sys_id of the reference
                payload[fieldName] = gr.getValue(fieldName);
            } else if (value != null && value !== '') {
                // Add other fields (string, integer, choice, etc.)
                payload[fieldName] = value.toString();
            }
            // If value is null/empty, we can skip adding it to keep the payload clean.
        }

        gs.info('Request ' + JSON.stringify(payload, null, 2));

        var jsonPayload = JSON.stringify(payload);
        var rest = new sn_ws.RESTMessageV2();
        rest.setEndpoint('https://dev347183.service-now.com/api/x_938076_now_utils/incident_data/createIncidentsfromOutbound');
        rest.setHttpMethod('POST');
        rest.setRequestHeader('Content-Type', 'application/json');
        rest.setRequestHeader('Accept', 'application/json');
        rest.setRequestHeader('Authorization', 'Bearer QJ2YXfyZA4qcWXqFr1CT_tCmwuLtidebRCL5hf2vlTIw6l8_4zvtt9OuKQiX3UuLCOiFb1o94a72eEE7vnbgFA');
        rest.setRequestBody(jsonPayload);

        // 6. Execute the request
        var response = rest.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        // 7. Log the results
        gs.print('--- REST API Call Results ---');
        gs.print('HTTP Status Code: ' + httpStatus);

        if (httpStatus === 201 || httpStatus === 200) {
            gs.print('Success: Incident data sent successfully.');
            try {
                var responseJson = JSON.parse(responseBody);
                gs.print('Response Body: ' + JSON.stringify(responseJson, null, 2));
            } catch (e) {
                gs.print('Success, but unable to parse response JSON. Raw body: ' + responseBody);
            }
        } else {
            gs.error('ERROR: REST call failed.');
            gs.error('Response Body: ' + responseBody);
            gs.error('Error Message: ' + response.getErrorMessage());
        }
    },




    createFixScript: function(fixScriptID) {
        try {
            var retry = 0;

            var payload = {};
            var requestData = new GlideRecord("sys_script_fix");
            requestData.get(fixScriptID);

            // Access the properties from the requestData object, not the request object
            payload.name = requestData.name ? requestData.name.toString() : "";
            payload.description = requestData.description ? requestData.description.toString() : "";
            payload.script = requestData.script ? requestData.script.toString() : "";
            var jsonPayload = JSON.stringify(payload);

            //gs.info('Request ' + jsonPayload);

            //gs.info('Request ' + JSON.stringify(payload, null, 2));
            var rest = new sn_ws.RESTMessageV2();
            rest.setEndpoint('https://dev225873.service-now.com/api/x_938076_backup_0/script_backups');
            rest.setHttpMethod('POST');
            rest.setRequestHeader('Content-Type', 'application/json');
            rest.setRequestHeader('Accept', 'application/json');
            rest.setRequestHeader('Authorization', gs.getProperty('x_938076_now_utils.dev225873Accesstoken'));
            rest.setRequestBody(jsonPayload);

            // 6. Execute the request
            var response = rest.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            // 7. Log the results
            gs.info('createFixScript --- REST API Call Results ---');
            gs.info('createFixScript HTTP Status Code: ' + httpStatus);

            if (httpStatus === 201 || httpStatus === 200) {
                //retry Info
                if (retry > 0) {
                    gs.addErrorMessage('Token Failure fixed re-submitting request')
                }
                //retry info
                gs.info('createFixScript Success: Incident data sent successfully.');
                try {
                    var responseJson = JSON.parse(responseBody);
                    gs.info('createFixScript Response Body: ' + JSON.stringify(responseJson, null, 2));
                } catch (e) {
                    gs.info('createFixScript Success, but unable to parse response JSON. Raw body: ' + responseBody);
                }
            } else {
                retry++;
                gs.addErrorMessage('Token Failure Retrying to Refresh token and re-requesting')
                this.refreshToken();
                this.createFixScript(fixScriptID);
                gs.error('createFixScript ERROR: REST call failed.');
                gs.error('createFixScript Response Body: ' + responseBody);
                gs.error('createFixScript Error Message: ' + response.getErrorMessage());
            }
        } catch (ex) {
            gs.info('createFixScript Error From Create Fix Script ' + ex)
        }
    },


    getIncidentsusingMidserver: function() {

        var incidentSysId = '28ed75c09747aa10a78db62de053af48';
        var midServerName = 'Crank Mid Server';
        var instanceUrl = gs.getProperty('glide.servlet.uri') + 'api/now/table/incident/' + incidentSysId;

        var rm = new sn_ws.RESTMessageV2();
        rm.setEndpoint(instanceUrl);
        rm.setHttpMethod('GET');
        rm.setMIDServer(midServerName);

        // FIX: Use setRequestHeader instead of setStringParameter
        var token = 'xL_cD2HJBtnc9hhom_B0oZCYglXrvhzeHcvy9h2v7Bx1HarbOhHfCvipiiA_VRTp8sgexVBwQUkbxd0jBGvwjA';
        rm.setRequestHeader('Authorization', 'Bearer ' + token);
        rm.setRequestHeader('Accept', 'application/json');

        var response = rm.executeAsync();
        response.waitForResponse(60);

        var httpStatus = response.getStatusCode();
        var responseBody = response.getBody();

        if (httpStatus == 200) {
            var incidentData = JSON.parse(responseBody);
            gs.info('Successfully Retrieved Incident: ' + incidentData.result.number);
        } else {
            gs.error('REST Call failed via MID Server with status: ' + httpStatus + '. Error: ' + response.getErrorMessage());
        }

    },



    getOAuthTokenForm: function() {

        try {


            var clientSecret = this.getParameter('sysparm_clientsecret');
            var clientid = this.getParameter('sysparm_clientid');
            var userName = this.getParameter('sysparm_userName');
            var userPassword = this.getParameter('sysparm_userPassword');
            var endPoint = this.getParameter('sysparm_endPoint');
            var formID = this.getParameter('sysparm_formID');
            var tableName = this.getParameter('sysparm_tableName');

            gs.info('clientSecret Crank' + clientSecret);
            gs.info('clientid Crank' + clientid);
            gs.info('userName Crank' + userName);
            gs.info('userPassword Crank' + userPassword);
            gs.info('endPoint Crank' + endPoint);
            gs.info('formID Crank' + formID);
            gs.info('tableName Crank' + tableName);


            var requestBody = 'grant_type=password' +
                '&client_id=' + encodeURIComponent(clientid) +
                '&client_secret=' + encodeURIComponent(clientSecret) +
                '&username=' + encodeURIComponent(userName) +
                '&password=' + encodeURIComponent(userPassword);

            gs.infO('Oauth Request Body ' + requestBody);

            var restMessage = new sn_ws.RESTMessageV2();
            restMessage.setEndpoint(endPoint + 'oauth_token.do');
            restMessage.setHttpMethod('POST');
            restMessage.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
            restMessage.setRequestBody(requestBody);

            var response = restMessage.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            gs.info('HTTP OAUTH Status ' + httpStatus);

            if (httpStatus === 200) {
                var tokenResponse = JSON.parse(responseBody);
                gs.info('OAuth Access Token: ' + tokenResponse.access_token);
                gs.info('OAuth Refresh Token: ' + tokenResponse.refresh_token);

                var gr = new GlideRecord(tableName);
                gr.get(formID);
                gr.access_token = tokenResponse.access_token;
                gr.refresh_token = tokenResponse.refresh_token;
                gr.update();
                gs.info('Token Generated Successfully')
                return tokenResponse;
            } else {
                gs.error('Failed to get OAuth token. Status: ' + httpStatus + ', Response: ' + responseBody);
                return null;
            }
        } catch (ex) {
            gs.error('Exception in getOAuthToken: ' + ex.getMessage());
            return null;
        }
    },

